def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != bg and grid[r][c] != 8]
    if not cells:
        return grid
    r0 = min(r for r,c,v in cells)
    r1 = max(r for r,c,v in cells)
    c0 = min(c for r,c,v in cells)
    c1 = max(c for r,c,v in cells)
    pattern = [(r-r0, c-c0, v) for r,c,v in cells]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8:
                top, left = r-2, c-2
                for dr, dc, v in pattern:
                    rr, cc = top+dr, left+dc
